129	    fn handle_input(&mut self, input: HarnessInput) {
130	        match input {
131	            HarnessInput::Quit => self.quit = true,
132	            HarnessInput::Interrupt => {
133	                self.ui.show_ctrl_c_exit_notice();
134	                if self.ui.focus() == PaneFocus::Right
135	                    && let Some(agent_id) = self.ui.selected_agent()
136	                {
137	                    self.transcript
138	                        .push(format!("work-leaf: sent Ctrl-C to {agent_id}"));
139	                }
140	            }
141	            HarnessInput::Backspace if self.ui.mode() == UiMode::Prompt => {
142	                self.backspace_prompt_char();
143	            }
144	            HarnessInput::Backspace if self.ui.mode() == UiMode::Insert => {
145	                self.backspace_chat_char();
146	            }
147	            HarnessInput::Enter if self.ui.mode() == UiMode::Prompt => {
148	                let line = self.prompt_buffer.trim().to_string();
149	                self.prompt_buffer.clear();
150	                self.prompt_cursor = 0;
151	                self.prompt_history_index = None;
152	                self.prompt_history_draft = None;
153	                self.ui.handle_key(UiKey::Esc);
154	                if !line.is_empty() {
155	                    self.prompt_history.push(line.clone());
156	                    self.transcript.push(format!("work-leaf> {line}"));
157	                    self.execute_prompt(&line);
158	                }
159	            }
160	            HarnessInput::Enter if self.ui.mode() == UiMode::Insert => {
161	                let message = self.chat_buffer.trim().to_string();
162	                self.chat_buffer.clear();
163	                self.chat_cursor = 0;
164	                self.chat_history_index = None;
165	                self.chat_history_draft = None;
166	                if !message.is_empty() {
167	                    self.chat_history.push(message.clone());
168	                    let target_agent = self.ui.selected_agent().cloned();
169	                    if let Some(agent_id) = target_agent.as_ref() {
170	                        self.name_chat_from_first_prompt(agent_id, &message);
171	                    }
172	                    let target = target_agent
173	                        .as_ref()
174	                        .map(AgentId::as_str)
175	                        .unwrap_or("work-leaf");
176	                    self.transcript.push(format!("{target}> {message}"));
177	                    self.transcript
178	                        .push("fixture reply: message recorded".to_string());
179	                }
180	            }
181	            HarnessInput::Char('/') if self.should_start_agent_slash_command() => {
182	                self.start_agent_slash_command();
183	            }
184	            HarnessInput::Char(ch) if self.ui.mode() == UiMode::Prompt => {
185	                self.insert_prompt_char(ch);
186	            }
187	            HarnessInput::Char(ch) if self.ui.mode() == UiMode::Insert => {
188	                self.insert_chat_char(ch);
189	            }
190	            HarnessInput::Key(UiKey::Left) if self.ui.mode() == UiMode::Prompt => {
191	                self.move_prompt_cursor_left();
192	            }
193	            HarnessInput::Key(UiKey::Right) if self.ui.mode() == UiMode::Prompt => {
194	                self.move_prompt_cursor_right();
195	            }
196	            HarnessInput::Key(UiKey::Up) if self.ui.mode() == UiMode::Prompt => {
197	                self.recall_prompt_history(-1);
198	            }
199	            HarnessInput::Key(UiKey::Down) if self.ui.mode() == UiMode::Prompt => {
200	                self.recall_prompt_history(1);
201	            }
202	            HarnessInput::Key(UiKey::Left) if self.should_route_chat_arrow() => {
203	                self.move_chat_cursor_left();
204	            }
205	            HarnessInput::Key(UiKey::Right) if self.should_route_chat_arrow() => {
206	                self.move_chat_cursor_right();
207	            }
208	            HarnessInput::Key(UiKey::Up) if self.should_route_chat_arrow() => {
209	                self.recall_chat_history(-1);
210	            }
211	            HarnessInput::Key(UiKey::Down) if self.should_route_chat_arrow() => {
212	                self.recall_chat_history(1);
213	            }
214	            HarnessInput::Key(UiKey::Esc) => {
215	                self.prompt_buffer.clear();
216	                self.prompt_cursor = 0;
217	                self.prompt_history_index = None;
218	                self.prompt_history_draft = None;
219	                let actions = self.ui.handle_key(UiKey::Esc);
220	                self.record_actions(actions);
221	            }
222	            HarnessInput::Key(key) => {
223	                let actions = self.ui.handle_key(key);
224	                self.record_actions(actions);
225	            }
226	            HarnessInput::Char(ch) => {
227	                let actions = self.ui.handle_key(UiKey::Char(ch));
228	                self.record_actions(actions);
229	            }
230	            HarnessInput::Backspace | HarnessInput::Enter => {}
231	        }
232	    }
