338	
339	    fn handle_key_inner(&mut self, key: UiKey) -> Vec<UiAction> {
340	        match key {
341	            UiKey::MouseClick { column, row } => {
342	                self.pending = None;
343	                return self.handle_mouse_click(column, row);
344	            }
345	            UiKey::MouseScrollUp { column, row } => {
346	                self.pending = None;
347	                self.handle_mouse_scroll(column, row, true);
348	                return Vec::new();
349	            }
350	            UiKey::MouseScrollDown { column, row } => {
351	                self.pending = None;
352	                self.handle_mouse_scroll(column, row, false);
353	                return Vec::new();
354	            }
355	            _ => {}
356	        }
357	
358	        if let Some(pending) = self.pending.take() {
359	            return self.handle_pending_key(pending, key);
360	        }
361	
362	        match key {
363	            UiKey::Esc => {
364	                self.mode = UiMode::Command;
365	                Vec::new()
366	            }
367	            UiKey::CtrlW if self.mode == UiMode::Command => {
368	                self.pending = Some(PendingKey::CtrlW);
369	                Vec::new()
370	            }
371	            UiKey::Char('g') if self.mode == UiMode::Command => {
372	                self.pending = Some(PendingKey::G);
373	                Vec::new()
374	            }
375	            UiKey::Char('i') if self.mode == UiMode::Command => {
376	                self.mode = UiMode::Insert;
377	                Vec::new()
378	            }
379	            UiKey::Char(':') if self.mode == UiMode::Command => {
380	                self.mode = UiMode::Prompt;
381	                Vec::new()
382	            }
383	            UiKey::Char(',') if self.mode == UiMode::Command => {
384	                self.left_visible = !self.left_visible;
385	                self.focus = if self.left_visible {
386	                    PaneFocus::Left
387	                } else {
388	                    PaneFocus::Right
389	                };
390	                Vec::new()
391	            }
392	            UiKey::Char('j') if self.mode == UiMode::Command && self.focus == PaneFocus::Left => {
393	                self.move_control_selection(1);
394	                self.select_control_row_surface();
395	                Vec::new()
396	            }
397	            UiKey::Down if self.mode == UiMode::Command && self.focus == PaneFocus::Left => {
398	                self.move_control_selection(1);
399	                self.select_control_row_surface();
400	                Vec::new()
401	            }
402	            UiKey::Right if self.mode == UiMode::Command && self.focus == PaneFocus::Left => {
403	                self.move_control_selection(1);
404	                self.select_control_row_surface();
405	                Vec::new()
406	            }
407	            UiKey::Char('k') if self.mode == UiMode::Command && self.focus == PaneFocus::Left => {
408	                self.move_control_selection(-1);
409	                self.select_control_row_surface();
410	                Vec::new()
411	            }
412	            UiKey::Up if self.mode == UiMode::Command && self.focus == PaneFocus::Left => {
413	                self.move_control_selection(-1);
414	                self.select_control_row_surface();
415	                Vec::new()
416	            }
417	            UiKey::Left if self.mode == UiMode::Command && self.focus == PaneFocus::Left => {
418	                self.move_control_selection(-1);
419	                self.select_control_row_surface();
420	                Vec::new()
421	            }
422	            UiKey::Char('l') if self.mode == UiMode::Command && self.focus == PaneFocus::Left => {
423	                self.open_control_selection();
424	                Vec::new()
425	            }
426	            UiKey::Char('x') if self.mode == UiMode::Command && self.focus == PaneFocus::Left => {
427	                self.hide_control_selection();
428	                Vec::new()
429	            }
430	            UiKey::Char('s') if self.mode == UiMode::Command => self.open_selected_same_pane(),
431	            UiKey::Char('t') if self.mode == UiMode::Command => self.open_selected_new_window(),
432	            UiKey::Char('f') if self.mode == UiMode::Command => self.fork_selected_agent(),
433	            _ => Vec::new(),
434	        }
435	    }
