1191	fn buffer_to_string(buffer: &Buffer) -> String {
1192	    const ANSI_REVERSE_VIDEO: &str = "\u{1b}[7m";
1193	    const ANSI_RESET: &str = "\u{1b}[0m";
1194	    let mut output = String::new();
1195	    for y in 0..buffer.area.height {
1196	        let mut reversed = false;
1197	        for x in 0..buffer.area.width {
1198	            let cell = buffer.get(x, y);
1199	            let cell_reversed = cell.modifier.contains(Modifier::REVERSED);
1200	            if cell_reversed != reversed {
1201	                output.push_str(if cell_reversed {
1202	                    ANSI_REVERSE_VIDEO
1203	                } else {
1204	                    ANSI_RESET
1205	                });
1206	                reversed = cell_reversed;
1207	            }
1208	            output.push_str(&cell.symbol);
1209	        }
1210	        if reversed {
