1236	fn visible_content(content: &str, width: u16, height: u16, scroll_rows: usize) -> String {
1237	    let height = usize::from(height);
1238	    let Some((history, prompt)) = split_chat_prompt(content) else {
1239	        return tail_visible_content(content, width, height, scroll_rows);
1240	    };
1241	
1242	    let prompt_rows = visual_row_count(prompt, width);
1243	    let history_height = height.saturating_sub(prompt_rows).max(1);
1244	    let visible_history = tail_visible_content(history, width, history_height, scroll_rows);
1245	    if visible_history.is_empty() {
1246	        prompt.to_string()
1247	    } else {
1248	        format!("{visible_history}\n{prompt}")
1249	    }
1250	}
1251	
1252	fn split_chat_prompt(content: &str) -> Option<(&str, &str)> {
1253	    let (history, prompt) = content.rsplit_once('\n')?;
1254	    prompt.starts_with("chat> ").then_some((history, prompt))
1255	}
1256	
1257	fn tail_visible_content(content: &str, width: u16, height: usize, scroll_rows: usize) -> String {
1258	    if content.is_empty() || height == 0 {
1259	        return String::new();
1260	    }
1261	
1262	    let lines = content.lines().collect::<Vec<_>>();
1263	    let rows_to_skip = scroll_rows.min(
1264	        lines
1265	            .iter()
1266	            .map(|line| visual_row_count(line, width))
1267	            .sum::<usize>()
1268	            .saturating_sub(height),
1269	    );
1270	    let mut visible = Vec::new();
1271	    let mut skipped_rows = 0_usize;
1272	    let mut used_rows = 0_usize;
1273	    for line in lines.iter().rev() {
1274	        let rows = visual_row_count(line, width);
1275	        if skipped_rows.saturating_add(rows) <= rows_to_skip {
1276	            skipped_rows = skipped_rows.saturating_add(rows);
1277	            continue;
1278	        }
1279	        if visible.is_empty() || used_rows.saturating_add(rows) <= height {
1280	            visible.push(*line);
1281	            used_rows = used_rows.saturating_add(rows);
1282	        } else {
1283	            break;
1284	        }
1285	    }
1286	    visible.reverse();
1287	    visible.join("\n")
1288	}
