461	    fn continue_escape_sequence(&mut self, byte: u8) -> bool {
462	        let Some(sequence) = self.escape_sequence.as_mut() else {
463	            return false;
464	        };
465	
466	        if sequence.bytes.len() == 1 && byte != b'[' {
467	            let sequence = self
468	                .escape_sequence
469	                .take()
470	                .expect("escape sequence is present");
471	            self.dispatch_pending_escape_if_needed(&sequence);
472	            return false;
473	        }
474	
475	        sequence.bytes.push(byte);
476	        if let Some((key, len)) = parse_key_sequence(&sequence.bytes) {
477	            if len == sequence.bytes.len() {
478	                let sequence = self
479	                    .escape_sequence
480	                    .take()
481	                    .expect("escape sequence is present");
482	                if sequence.escape_dispatched
483	                    && sequence.mode_before == UiMode::Insert
484	                    && self.ui.mode() != UiMode::Insert
485	                {
486	                    let actions = self.ui.handle_key(UiKey::Char('i'));
487	                    self.record_actions(actions);
488	                }
