+    fn apply_visual_selection(&self, buffer: &mut Buffer, right_content: &str) {
+        let Some(selection) = self.visual_selection.as_ref() else {
+            return;
+        };
+        let Some(inner) = self.visual_pane_inner_rect(selection.pane) else {
+            return;
+        };
+        if inner.width == 0 || inner.height == 0 {
+            return;
+        }
+        let lines = self.visual_lines(selection.pane, right_content);
+        for (line, start, end) in visual_selection_ranges(selection, &lines, false) {
+            if line >= usize::from(inner.height) {
+                continue;
+            }
+            let start = start.min(usize::from(inner.width));
+            let end = end.min(usize::from(inner.width));
+            let row = inner.y.saturating_add(line as u16);
+            for column in start..end {
