+            PaneFocus::Left => return None,
+            PaneFocus::Right => Rect::new(layout.left_width, 0, layout.right_width, body_height),
+        };
+        Some(Rect::new(
+            outer.x.saturating_add(1),
+            outer.y.saturating_add(1),
+            outer.width.saturating_sub(2),
+            outer.height.saturating_sub(2),
